template<class C,class T>Status field(C& c,const char* name,T& v,const MovementRecordCodecSelection& selection){return c.object(name,[&](auto& x){return value(x,v,selection);});}
template<class C,class T>Status value(C& c,std::vector<T>& v,const MovementRecordCodecSelection& selection){return c.sequence("items",v,[&](auto& x,T& row){return value(x,row,selection);});}
template<class C,class T>Status value(C& c,std::optional<T>& v,const MovementRecordCodecSelection& selection){return c.optional("optional",v,[&](auto& x,T& row){return value(x,row,selection);});}
template<std::size_t I=0,class V>bool construct_variant(V& v,Integer index){if constexpr(I<std::variant_size_v<V>){if(index==Integer(I)){v.template emplace<I>();return true;}return construct_variant<I+1>(v,index);}return false;}
template<class C,class...T>Status value(C& c,std::variant<T...>& v,const MovementRecordCodecSelection& selection){Integer tag=Integer(v.index());c.field("variant",tag);if(c.reading()&&c.status().ok&&!construct_variant(v,tag))return c.reject("InvalidMovementVariant");if(c.status().ok)return std::visit([&](auto& item){return value(c,item,selection);},v);return c.status();}
template<class C,class A,class B>Status value(C& c,std::pair<A,B>& v,const MovementRecordCodecSelection& selection){c.object("first",[&](auto& x){return value(x,v.first,selection);});return c.object("second",[&](auto& x){return value(x,v.second,selection);});}
template<class C>Status value(C& c,CanonicalFraction& v,const MovementRecordCodecSelection&){return exact_fields::fraction(c,v);}
template<class C>Status value(C& c,WorldMoment& v,const MovementRecordCodecSelection&){return exact_fields::moment(c,v);}
template<class C>Status value(C& c,MomentOwnerSource& v,const MovementRecordCodecSelection& selection){field(c,"source_ref",v.source_ref,selection);return c.field("source_schema",v.source_schema);}
template<class T,class F>Outcome<T> decode_original_record(F&& f){try{return {true,f(),{}};}catch(const boundary::DecodeFailure& error){return {false,{},error.error};}}
template<class C>Status value(C& c,Location& v,const MovementRecordCodecSelection& selection){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)return common_checkpoint::location(c,v);else return c.foreign_record(v,[&](const BoundaryValue& raw){return decode_original_record<Location>([&]{return boundary::decode_location(raw,"movement/location",selection.carrier_location_enabled);});},[&](ProjectionWriter& w,const Location& row){return emit_common_location_fields(w,row,selection.carrier_location_enabled);});}
template<class C>Status value(C& c,Owner& v,const MovementRecordCodecSelection&){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)return common_checkpoint::owner(c,v);else return c.foreign_record(v,[](const BoundaryValue& raw){return decode_original_record<Owner>([&]{return boundary::decode_owner(raw,"movement/owner");});},[](ProjectionWriter& w,const Owner& row){w.order_fields(row.field_order);return emit_common_owner_fields(w,row);});}
template<class C>Status value(C& c,ReservationRef& v,const MovementRecordCodecSelection& selection){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)return common_checkpoint::reservation(c,v,"reservation_id");else{if(!selection.typed_reservations)return c.reject("ExactTransportTypedReservationRequired");return c.foreign_record(v,[&](const BoundaryValue& raw){return decode_original_record<ReservationRef>([&]{return boundary::decode_reservation_ref(raw,"movement/reservation",selection.domain_activity_reservations);});},[&](ProjectionWriter& w,const ReservationRef& row){return emit_common_reservation_fields(w,row,true,selection.domain_activity_reservations);});}}
template<class C>Status value(C& c,InventoryEntryEvidence& v,const MovementRecordCodecSelection& selection){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)return visit_inventory_entry_evidence(c,v);else return c.foreign_record(v,[&](const BoundaryValue& raw){return decode_inventory_entry_evidence(raw,selection.common_resources);},[&](ProjectionWriter& w,const InventoryEntryEvidence& row){return emit_inventory_entry_evidence_fields(w,row,selection.common_resources);});}
template<class C>Status value(C& c,MilitaryGroupOrderAcceptance& v,const MovementRecordCodecSelection&){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)return visit_military_group_order_acceptance(c,v);else return c.foreign_record(v,decode_military_group_order_acceptance,emit_military_group_order_acceptance_fields);}
template<class C>Status value(C& c,TransportExpenseAuthority& v,const MovementRecordCodecSelection& selection){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>){auto status=visit_transport_expense_authority(c,v);if(!status.ok)return status;}else{auto status=c.foreign_record(v,[](const BoundaryValue& raw,ScopedCheckpointJsonDecode& budget){return decode_transport_expense_authority(raw,budget);},emit_transport_expense_authority_fields);if(!status.ok)return status;}if(selection.group_version==4&&std::holds_alternative<HouseholdPurchaseExpenseAuthority>(v))return c.reject("HouseholdTransportAuthorityRequiresGroup5");return c.status();}
template<class C>Status value(C& c,GroupJourneyFunding& v,const MovementRecordCodecSelection& selection){if((selection.group_version==6||selection.group_version==7)){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)return visit_group_journey_funding(c,v);else return c.foreign_record(v,decode_group_journey_funding,emit_group_journey_funding_fields);}if(selection.group_version!=4&&selection.group_version!=5)return c.reject("UnsupportedGroupTransportLayout");if(c.reading())v.emplace<TransportExpenseAuthority>();auto* original=std::get_if<TransportExpenseAuthority>(&v);if(!original)return c.reject("MilitaryMarchFundingRequiresGroupSuccessorLayout");return value(c,*original,selection);}
template<class C>Status value(C& c,TransportPaymentReceipt& v,const MovementRecordCodecSelection&){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)return visit_transport_payment_receipt(c,v);else return c.foreign_record(v,decode_transport_payment_receipt,emit_transport_payment_receipt_fields);}
template<class C>Status value(C& c,WorkUnits& v,const MovementRecordCodecSelection& selection){return field(c,"value",v.value,selection);}
template<class C>Status value(C& c,HalfDayDuration& v,const MovementRecordCodecSelection& selection){return field(c,"value",v.value,selection);}
template<class C>Status value(C& c,MomentSpan& v,const MovementRecordCodecSelection& selection){field(c,"from",v.from,selection);return field(c,"to",v.to,selection);}
template<class C>Status value(C& c,GroupJourneyTerminalOutcome& v,const MovementRecordCodecSelection& selection){Integer tag=Integer(v);c.field("enum",tag);if(tag<0||tag>1)return c.reject("InvalidMovementEnum");if(c.reading()&&c.status().ok)v=GroupJourneyTerminalOutcome(tag);return c.status();}
template<class C>Status value(C& c,TerrainOriginalClosingPolicy& v,const MovementRecordCodecSelection& selection){Integer tag=Integer(v);c.field("enum",tag);if(tag<0||tag>1)return c.reject("InvalidMovementEnum");if(c.reading()&&c.status().ok)v=TerrainOriginalClosingPolicy(tag);return c.status();}
template<class C>Status value(C& c,CarriedLocation::CarrierKind& v,const MovementRecordCodecSelection& selection){Integer tag=Integer(v);c.field("enum",tag);if(tag<0||tag>2)return c.reject("InvalidMovementEnum");if(c.reading()&&c.status().ok)v=CarriedLocation::CarrierKind(tag);return c.status();}
