// 仅此拥有型嵌套联合的 JSON/投影隔开两层判别；二进制继续原两 tag 字节序。
// 字符串分支仍用原 value 字段；读写共用同一有限 0/1 分支，未知/重复字段仍交原守门拒绝。
template<class C>Status value(C& c,InventorySpatialBinding& v,const MovementRecordCodecSelection& selection){
 field(c,"inventory_id",v.inventory_id,selection);
 if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)
  field(c,"placement",v.placement,selection);
 else c.object("placement",[&](auto& x){
  Integer tag=Integer(v.placement.index());x.field("variant",tag);
  if(!x.status().ok)return x.status();
  if(tag<0||tag>1)return x.reject("InvalidMovementVariant");
  if(x.reading()){
   if(tag==0)v.placement.template emplace<SpatialCarrierRef>();
   else v.placement.template emplace<StableId>();
  }
  if(tag==0)return field(x,"carrier",std::get<SpatialCarrierRef>(v.placement),selection);
  return value(x,std::get<StableId>(v.placement),selection);
 });
 field(c,"source_ref",v.source_ref,selection);field(c,"revision",v.revision,selection);return c.status();
}
